import {esc} from './ui.mjs';
const colors={yellow:'黄色',green:'绿色',blue:'蓝色',pink:'粉色'};
export function mountPdfAnnotations({viewer,container,resourceId,resourceKind='file',ownerId,signal,fetchImpl=(...args)=>fetch(...args)}={}){
 const doc=container.ownerDocument,win=doc.defaultView,controller=new win.AbortController(),tools=container.querySelector('.lit-pdf-tools');let live=true,items=[],selection=[],loaded=false,busy=false,editing=null;
 const current=()=>live&&container.isConnected&&!signal?.aborted;
 const control=doc.createElement('button');control.type='button';control.className='lit-pdf-annotations-toggle';control.textContent='标注';control.setAttribute('aria-expanded','false');control.setAttribute('aria-label','打开 PDF 标注');tools.append(control);
 const bar=doc.createElement('div');bar.className='lit-pdf-selection-bar';bar.hidden=true;bar.innerHTML='<span>选中文字后选择高亮颜色</span>'+Object.entries(colors).map(([key,name])=>`<button type="button" data-mark-color="${key}" aria-label="${name}高亮" title="${name}高亮"></button>`).join('')+'<button type="button" data-mark-note>添加备注</button><button type="button" data-mark-cancel aria-label="取消选中文字">×</button>';
 const panel=doc.createElement('aside');panel.className='lit-pdf-annotations';panel.hidden=true;panel.setAttribute('aria-label','PDF 标注管理');panel.innerHTML='<header><b>我的标注</b><button type="button" data-mark-close aria-label="关闭标注管理">×</button></header><p role="status" data-mark-status>正在读取云端标注…</p><button type="button" data-mark-reload hidden>重新读取标注</button><form data-mark-editor hidden><label>标注颜色<select name="color">'+Object.entries(colors).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')+'</select></label><label>备注<textarea name="note" maxlength="3000" rows="3" placeholder="记录你的理解、疑问或想法"></textarea></label><div><button type="submit">保存标注</button><button type="button" data-mark-edit-cancel>取消编辑</button></div></form><div data-mark-list></div>';
 container.append(bar,panel);const place=()=>{const top=tools.offsetHeight+6;bar.style.top=top+'px';panel.style.top=top+'px';};place();const sizeObserver=win.ResizeObserver?new win.ResizeObserver(place):null;sizeObserver?.observe(tools);const status=panel.querySelector('[data-mark-status]'),form=panel.querySelector('form'),list=panel.querySelector('[data-mark-list]'),reload=panel.querySelector('[data-mark-reload]');
 const path='/api/literature/reader/'+resourceKind+'/'+encodeURIComponent(resourceId)+'/annotations';
 async function request(body){const r=await fetchImpl(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',redirect:'error',signal:controller.signal,headers:{'Content-Type':'application/json','X-PaperKnow-User':ownerId},...(body?{body:JSON.stringify({...body,expectedUserId:ownerId})}:{})});const data=await r.json();if(!r.ok)throw Error(typeof data.error==='string'?data.error:'标注暂未保存，请重试');if(!current())throw new win.DOMException('页面已关闭','AbortError');return data;}
 function open(value=true){panel.hidden=!value;control.setAttribute('aria-expanded',String(value));}
 function render(){viewer.setAnnotations(items);control.textContent='标注'+(items.length?' '+items.length:'');list.innerHTML=items.map(item=>`<article data-mark-id="${esc(item.id)}"><button type="button" data-mark-jump="${esc(item.id)}"><i data-color="${item.color}"></i><b>第 ${item.page} 页</b><span>${esc(item.quote.slice(0,200))}</span></button>${item.note?`<p>${esc(item.note)}</p>`:''}<div><button type="button" data-mark-edit="${esc(item.id)}">编辑</button><button type="button" data-mark-delete="${esc(item.id)}">删除</button></div></article>`).join('')||'<p class="lit-mark-empty">在 PDF 中选中文字，即可高亮并记录想法。</p>';}
 async function load(){try{reload.hidden=true;const result=await request();items=result.items;loaded=true;render();if(editing){const latest=items.find(item=>item.id===editing.id);if(latest){const changed=latest.version!==editing.version;editing=latest;status.textContent=changed?'已读取最新标注，请核对备注后再次保存。':'标注已与账户同步';form.querySelector('button[type=submit]').disabled=false;}else{status.textContent='原标注已删除，当前备注仍保留，请复制后再新建标注。';form.querySelector('button[type=submit]').disabled=true;}}else status.textContent='标注已与账户同步';}catch(error){if(current()){loaded=false;status.textContent=error.message;reload.hidden=false;}}}
 function editor(item){editing=item;form.hidden=false;form.querySelector('button[type=submit]').disabled=false;form.elements.note.value=item?.note||'';form.elements.color.value=item?.color||'yellow';open();form.elements.note.focus({preventScroll:true});}
 async function save(color,note=''){
  if(busy)return;if(!loaded){open();status.textContent='请先成功读取云端标注，再添加或编辑';return;}const groups=editing?[editing]:selection;if(!groups.length)return;busy=true;form.querySelector('button[type=submit]').disabled=true;bar.querySelectorAll('button').forEach(b=>b.disabled=true);status.textContent='正在保存标注…';open();
  try{for(const group of groups){const id=group.id||group.requestId||(group.requestId=win.crypto.randomUUID()),result=await request({id,action:group.id?'update':'create',...(group.id?{version:group.version}:{}),page:group.page,quote:group.quote,rects:group.rects,color,note});const index=items.findIndex(i=>i.id===result.item.id);if(index<0)items.push(result.item);else items[index]=result.item;render();}selection=[];editing=null;bar.hidden=true;form.hidden=true;win.getSelection()?.removeAllRanges();status.textContent='已保存到云端，重新打开文献仍可查看';}catch(error){if(current()){status.textContent=error.message;reload.hidden=false;}}finally{if(current()){busy=false;form.querySelector('button[type=submit]').disabled=false;bar.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 }
 const unselect=viewer.subscribeSelection(groups=>{if(busy)return;if(!form.hidden&&form.elements.note.value.trim()){open();status.textContent='请先保存当前备注，再添加新标注。';return;}selection=groups;editing=null;form.hidden=true;bar.hidden=false;bar.querySelector('span').textContent='已选 '+groups.reduce((n,g)=>n+g.quote.length,0)+' 字';});
 const unmark=viewer.subscribeAnnotation(id=>{const item=items.find(i=>i.id===id);if(item)editor(item);});
 control.onclick=()=>open(panel.hidden);panel.querySelector('[data-mark-close]').onclick=()=>open(false);reload.onclick=()=>void load();
 bar.onpointerdown=event=>event.preventDefault();bar.querySelectorAll('[data-mark-color]').forEach(button=>button.onclick=()=>void save(button.dataset.markColor));bar.querySelector('[data-mark-note]').onclick=()=>editor(null);bar.querySelector('[data-mark-cancel]').onclick=()=>{bar.hidden=true;selection=[];win.getSelection()?.removeAllRanges();};
 form.onsubmit=event=>{event.preventDefault();void save(form.elements.color.value,form.elements.note.value);};form.querySelector('[data-mark-edit-cancel]').onclick=()=>{form.hidden=true;editing=null;};
 list.onclick=async event=>{if(busy)return;const jump=event.target.closest('[data-mark-jump]'),edit=event.target.closest('[data-mark-edit]'),del=event.target.closest('[data-mark-delete]'),id=jump?.dataset.markJump||edit?.dataset.markEdit||del?.dataset.markDelete,item=items.find(i=>i.id===id);if(!item)return;if(jump){await viewer.setView({...viewer.getView(),page:item.page,fraction:Math.max(0,item.rects[0].y-.15)},{notify:true});return;}if(edit){editor(item);return;}busy=true;try{await request({id:item.id,action:'delete',version:item.version});items=items.filter(i=>i.id!==item.id);if(editing?.id===item.id){editing=null;form.hidden=true;}render();status.textContent='标注已删除';}catch(error){if(current()){status.textContent=error.message;reload.hidden=false;}}finally{busy=false;}};
 const dispose=()=>{if(!live)return;live=false;controller.abort();sizeObserver?.disconnect();signal?.removeEventListener('abort',dispose);unselect();unmark();control.remove();bar.remove();panel.remove();};signal?.addEventListener('abort',dispose,{once:true});void load();return{dispose,reload:load};
}
